const KEYS=['life','office','business','creator','learner'];
let state={page:0,persona:1,step:0,repeat:0,idea:0,node:0,system:0,case:0,cycle:0,auto:false,delivery:1,notes:false};
const slides=[...document.querySelectorAll('.slide')];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const dat=()=>MODE[KEYS[state.persona]];
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function go(n){const x=Math.max(0,Math.min(slides.length-1,Number(n)));state.page=x;slides.forEach((s,i)=>{s.classList.toggle('active',i===x);s.setAttribute('aria-hidden',i===x?'false':'true');if(i===x)s.scrollTop=0});$('#footer-counter').textContent=String(x+1).padStart(2,'0')+' / 11';$('#footer-topic').textContent=slides[x].dataset.title;$('#progress-fill').style.width=`${(x+1)/slides.length*100}%`;$('#prev').disabled=x===0;$('#next').disabled=x===10;try{history.replaceState(null,'','#'+String(x+1).padStart(2,'0'))}catch{};renderNotes();}
window.go=go;
function setPersona(i){state.persona=i;state.step=0;state.node=0;state.repeat=0;state.case=0;state.idea=0;state.cycle=0;renderAll();try{sessionStorage.setItem('personal-ai-persona',String(i))}catch{}}
function renderQuestions(){const p=dat();$('#problem-list').innerHTML=p.questions.map((a,i)=>`<button class="problem" data-issue="${i}"><span class="problem-num">0${i+1} /</span><div><strong>${esc(a[0])}</strong><small>${esc(a[1])}</small></div><span class="arr">↗</span></button>`).join('');$$('[data-issue]').forEach(b=>b.onclick=()=>go([2,3,4,5][Number(b.dataset.issue)]));}
function renderProcess(){const p=dat();$('#process-band').innerHTML=p.steps.map((a,i)=>`<button class="process-step ${i===state.step?'active':''}" data-process="${i}"><span class="step-no">STEP / 0${i+1}</span><strong>${esc(a[0])}</strong><span>↗</span></button>`).join('');$('#process-title').textContent=`0${state.step+1} / ${p.steps[state.step][0]}`;$('#process-detail').textContent=p.steps[state.step][1];$$('[data-process]').forEach(b=>b.onclick=()=>{state.step=Number(b.dataset.process);renderProcess()});}
function renderRepeat(){const p=dat(), a=p.repeat;$('#repeat-lane').innerHTML=a.map((x,i)=>`<div class="repeat-row ${state.repeat===2&&i<3?'done':''}"><b>0${i+1}</b><span>${esc(state.repeat===2&&i<3?['从历史中找到资料','复用已确认的处理规则','专注本次新增变化'][i]:x)}</span><span>${state.repeat===2&&i<3?'✓':'↗'}</span></div>`).join('');$('#repeat-quote').textContent=[`第一次：你可能需要逐步完成“${a[0]}、${a[1]}”等工作。`,`第二次：如果只留下结果，同一套步骤可能还得再来一遍。`,`可复用：${p.repeatFresh}`][state.repeat];$$('[data-repeat]').forEach(b=>b.classList.toggle('active',Number(b.dataset.repeat)===state.repeat));}
function renderVault(){const p=dat();$('#vault-files').innerHTML=p.files.map((x,i)=>`<button class="vault-file ${i===Math.max(0,state.node-1)?'active':''}" data-file="${i}">◈ ${esc(x)}</button>`).join('');$('#node-title').textContent=['当前任务','项目背景','处理规则','历史结果','下一次复用'][state.node];$('#node-desc').textContent=p.nodeDesc[state.node];$$('.graph-node').forEach(el=>el.classList.toggle('active',Number(el.dataset.node)===state.node));$$('[data-file]').forEach(b=>b.onclick=()=>{state.node=Number(b.dataset.file)+1;renderVault()});}
function renderIdea(){const p=dat();$('#idea-request').textContent='“'+p.idea+'”';const v=state.idea;$('#idea-window-status').textContent=['01 / UNDERSTAND THE IDEA','02 / DESIGN THE STEPS','03 / TRY THE PROTOTYPE'][v];$('#idea-preview').innerHTML=`<div class="smallcaps">CODEX × IDEA / ${String(v+1).padStart(2,'0')}</div><div class="preview-title">${esc(p.preview[v])}</div>${v===0?`<p class="preview-desc">不必从代码开始。先告诉 AI：你遇到什么问题，希望得到怎样的结果。</p><div class="preview-bar" style="--fill:22%"></div>`:v===1?`<p class="preview-desc">把输入、需要处理的内容和最终输出拆开，让一个模糊想法逐步变成可执行的方案。</p><div class="preview-bar" style="--fill:61%"></div>`:`<div class="preview-metric">${esc(p.metricValue)}</div><p class="preview-desc">${esc(p.metric)} · 示例预览</p><div class="preview-bar" style="--fill:88%"></div>`}`;$$('[data-idea]').forEach(b=>b.classList.toggle('active',Number(b.dataset.idea)===v));}
const FLOW=[['你','提出自己的真实问题','先说明现在面临什么困难，想获得怎样的结果。'],['Codex','整理并执行任务','协助分析问题、处理资料，必要时制作简单的工具。'],['你','确认有用的结果','检查成果是否符合实际目标，找出真正值得保留的方法。'],['Obsidian','保存关键经验','让项目背景、处理规则、结论和历史记录有一个长期位置。'],['再一次使用','从已有积累继续','新的任务可以参考相关历史，不必每次重新开始。']];
function renderSystem(){$('#system-flow').innerHTML=FLOW.map((x,i)=>`<button class="sys-step ${i===state.system?'active':''}" data-system="${i}"><b>0${i+1} / ${['YOU','CODEX','YOU','OBSIDIAN','NEXT'][i]}</b><strong>${esc(['提出问题','辅助执行','理解结果','保存经验','再次复用'][i])}</strong></button>`).join('');$('#system-role').textContent=`0${state.system+1} / ${['YOU','CODEX','YOU','OBSIDIAN','REUSE'][state.system]}`;$('#system-heading').textContent=FLOW[state.system][1];$('#system-detail').textContent=FLOW[state.system][2];$('#system-example').textContent=dat().examples[[0,0,0,1,2][state.system]];$$('[data-system]').forEach(b=>b.onclick=()=>{state.system=Number(b.dataset.system);renderSystem()});}
function renderCases(){const p=dat();$('#scene-menu').innerHTML=NAMES.map((name,i)=>`<button class="scene-item ${state.persona===i?'active':''}" data-scene="${i}"><b>0${i+1}</b>${esc(name)} <span style="margin-left:auto;color:var(--blue)">↗</span></button>`).join('');const c=p.cases[state.case];$('#case-label').textContent=`0${state.persona+1} / ${EN[state.persona]} · ${p.desc}`;$('#case-title').textContent=c[0];$('#case-problem').textContent=c[1];$('#case-codex').textContent=c[2];$('#case-memory').textContent=c[3];$$('[data-scene]').forEach(b=>b.onclick=()=>setPersona(Number(b.dataset.scene)));$$('[data-case]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.case)===state.case);b.onclick=()=>{state.case=Number(b.dataset.case);renderCases()}});}
function renderCycle(){const a=dat().cycle[state.cycle];$('#cycle-left').textContent=a[0];$('#cycle-right').textContent=a[1];$('#cycle-text').textContent=a[2];$('#cycle-index').textContent='0'+(state.cycle+1);$('#cycle-lead').textContent=['第一份成果当然重要。但如果方法没有留下来，下一次可能仍然从头开始。','第二次开始，相关经验就有机会成为新的起点。','随着重复实践，方法逐步完善，形成自己的长期积累。'][state.cycle];$$('[data-cycle]').forEach(b=>b.classList.toggle('active',Number(b.dataset.cycle)===state.cycle));}
function renderDelivery(){$$('#delivery-description');$('#delivery-description').textContent=['从零学习和亲手搭建，逐渐掌握日常维护能力。','在指导下参与关键操作，逐渐建立独立使用的能力。','按照实际需求交付可使用的系统，再学习必要的操作。'][state.delivery];$$('[data-delivery]').forEach(b=>b.classList.toggle('active',Number(b.dataset.delivery)===state.delivery));}
function renderAll(){$$('.persona-label').forEach(x=>x.textContent=NAMES[state.persona]);renderQuestions();renderProcess();renderRepeat();renderVault();renderIdea();renderSystem();renderCases();renderCycle();renderDelivery();}
function openPersona(){renderPicker();$('#persona-dialog').showModal()}
function renderPicker(){$('#personas').innerHTML=NAMES.map((a,i)=>`<button class="persona-card ${state.persona===i?'chosen':''}" data-pick-id="${i}"><b>0${i+1} / ${esc(a)}</b><span>${esc(MODE[KEYS[i]].desc)} · 以你熟悉的问题理解 AI</span></button>`).join('');$$('[data-pick-id]').forEach(b=>b.onclick=()=>{setPersona(Number(b.dataset.pickId));$('#persona-dialog').close()})}
const rawNotes=JSON.parse($('#speaker-notes').textContent);
function renderNotes(){if(!state.notes)return;$('#notes-scroll').innerHTML=rawNotes[state.page];$('#notes-scroll').scrollTop=0;}
function toggleNotes(force){state.notes=typeof force==='boolean'?force:!state.notes;$('#notes-panel').classList.toggle('open',state.notes);$('#notes-toggle').setAttribute('aria-pressed',String(state.notes));renderNotes();}
function fillIndex(){$('#overview-items').innerHTML=slides.map((s,i)=>`<button data-goto="${i}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.dataset.title)}</button>`).join('');$$('[data-goto]').forEach(b=>b.onclick=()=>{$('#overview-dialog').close();go(Number(b.dataset.goto))});}
$$('[data-jump]').forEach(b=>b.onclick=()=>go(Number(b.dataset.jump)-1));$$('[data-pick]').forEach(b=>b.onclick=openPersona);$('#persona-picker').onclick=openPersona;$('#brand-home').onclick=(e)=>{e.preventDefault();go(0)};$('#overview-toggle').onclick=()=>{$('#overview-dialog').showModal()};$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#prev').onclick=()=>go(state.page-1);$('#next').onclick=()=>go(state.page+1);$('#notes-toggle').onclick=()=>toggleNotes();$('#close-notes').onclick=()=>toggleNotes(false);$('#auto-toggle').onclick=()=>{state.auto=!state.auto;document.body.classList.toggle('auto-on',state.auto);$('#auto-toggle').textContent=`AUTO / ${state.auto?'ON':'OFF'}`;$('#auto-toggle').setAttribute('aria-pressed',String(state.auto))};
$$('[data-repeat]').forEach(b=>b.onclick=()=>{state.repeat=Number(b.dataset.repeat);renderRepeat()});$$('[data-idea]').forEach(b=>b.onclick=()=>{state.idea=Number(b.dataset.idea);renderIdea()});$$('[data-cycle]').forEach(b=>b.onclick=()=>{state.cycle=Number(b.dataset.cycle);renderCycle()});$$('[data-delivery]').forEach(b=>b.onclick=()=>{state.delivery=Number(b.dataset.delivery);renderDelivery()});
$$('.graph-node').forEach(n=>{const act=()=>{state.node=Number(n.dataset.node);renderVault()};n.addEventListener('click',act);n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act()}})});
$('#copy-problem').onclick=async()=>{let v=$('#my-problem').value.trim();if(!v){$('#copy-status').textContent='先填写你想解决的事情。';$('#my-problem').focus();return;}let msg=`我希望用个人 AI 系统解决这个真实问题：${v}\n我想先讨论适合的处理方式和需要准备的资料。`;let success=false;try{await navigator.clipboard.writeText(msg);success=true}catch(e){const el=document.createElement('textarea');el.value=msg;el.style.position='fixed';el.style.left='-9999px';document.body.append(el);el.select();try{success=document.execCommand('copy')}catch(e){}el.remove()}$('#copy-status').textContent=success?'已复制问题描述；可粘贴到微信或其他沟通窗口。':'无法自动复制，请选中文字手动复制。';if(!success){$('#my-problem').focus();$('#my-problem').select()}};
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(document.activeElement&&/TEXTAREA|INPUT/.test(document.activeElement.tagName))return;if(e.key==='Escape'&&state.notes){toggleNotes(false);return}if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();go(state.page+1)}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();go(state.page-1)}if(e.key.toLowerCase()==='n'&&!e.ctrlKey){toggleNotes()}});
let touchX=0,touchY=0;document.querySelector('.stage').addEventListener('touchstart',e=>{touchX=e.touches[0].clientX;touchY=e.touches[0].clientY},{passive:true});document.querySelector('.stage').addEventListener('touchend',e=>{if(window.innerWidth<=720)return;const dx=e.changedTouches[0].clientX-touchX,dy=e.changedTouches[0].clientY-touchY;if(Math.abs(dx)>90&&Math.abs(dx)>Math.abs(dy)*1.5)go(state.page+(dx<0?1:-1))},{passive:true});
try{let stored=Number(sessionStorage.getItem('personal-ai-persona'));if(Number.isInteger(stored)&&stored>=0&&stored<=4)state.persona=stored}catch{}
fillIndex();renderAll();let h=Number((location.hash||'').slice(1));go(h>=1&&h<=11?h-1:0);

